import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"43、【夬】 乾下兑上","description":"周易尚氏学 - 43、【夬】 乾下兑上","frontmatter":{"title":"43、【夬】 乾下兑上","description":"周易尚氏学 - 43、【夬】 乾下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/048.md","filePath":"zh/classics/shangshi/048.md"}'),h={name:"zh/classics/shangshi/048.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_43、【夬】-乾下兑上" tabindex="-1">43、【夬】 乾下兑上 <a class="header-anchor" href="#_43、【夬】-乾下兑上" aria-label="Permalink to “43、【夬】 乾下兑上”">​</a></h1><p>王育云。夹即古文块字。按礼内则。右佩块。释文本又作决。诗小雅。决拾既饮是也。而夬决。故夬与决同。说文玉佩也。广韵合同似环而有缺。夬乾为玉为圜。兑上缺。俨然块形也。而决者绝也。左传晋献公赐太子申生块。以示决绝。卦以五阳决一阴。故谓之夬也。归藏以夬为规。规圜也。夬重乾。乾圜故为规。决亦圜。然上缺。是周易取象。与归藏同而更切也。乾为王。伏艮为庭。一阴履五阳之上。故曰扬于王庭。兑口为号。厉危。孚号有厉者。言阴虽孚于阳。为阳所说。然穷处于上。须危厉自警也。兑口故曰告。兑为斧钺。故曰戎。说文戎兵也。礼月令以习王戎。注弓殳矛戈战。伏艮为邑。告自邑。不利即戎者。言一阴危处于上。告诫国人。不可妄动也。皆指上六言也。利有攸往。谓五。夬本阳息卦。五息而往则阴尽。夬者决也。决者绝也。阳决阴也。</p><p>彖曰。夬。决也。刚决柔也。健而说。决而和。扬于王庭。柔乘五刚也 孚号有后。其危乃光也。告自邑。不利即戎。所尚乃穷也。利有攸往。刚长乃终也。</p><p>下健上说。说故和。其危乃光者。危谓阴退。阴退则阳长。阳长故光。所尚乃穷。申不利即戎之故也。阳长乃终。终谓阴尽也。</p><p>象曰。泽上于天。夬。君子以施禄及下。居德则忌。</p><p>禄谓恩泽。泽在天上无用。故君子思以下施。乾为富。故为德。德得同。苟子礼论篇。贵始得之本也。注得当为德。居积也。下乾。二至四。三至五。皆乾。乾多故曰居德。居德则忌者。言蓄积大多。多藏厚亡。为人所忌也。象辞每相反以取义。此亦其一也。</p><p>初九。壮于前趾。往不胜为咎。</p><p>初震爻。震足故曰趾。震动故曰前趾。壮。伤也。阳遇阳得敌。故伤于前趾。故往不胜而有咎矣。趾荀作止。晁氏云止古文。按说文有止无趾。止即足之象形字。加足者非也。</p><h3 id="象曰。不胜而往。咎也。" tabindex="-1">象曰。不胜而往。咎也。 <a class="header-anchor" href="#象曰。不胜而往。咎也。" aria-label="Permalink to “象曰。不胜而往。咎也。”">​</a></h3><p>前有重阳。所遇皆敌。不胜必矣。明知不胜而往。宜其有咎。</p><p>九二。惕号。莫夜有戎。勿恤。</p><p>乾为惕为言。故曰惕号。言有所警戒也。二应在五。五兑。兑为昧谷。故为莫为夜。兑为兵戎。故曰莫夜有戎。言有寇警也。然五不应二。故虽莫夜有戎。无忧也。乾为惕故为忧。旧解因不知勿恤之故何在。故用象皆误。岂知随象云。君子以晌晦人宴息。晌晦即谓兑。然则兑为莫夜。易有明象。而兑五不应二。故虽有虚惊。实不足忧恐也。</p><h3 id="象曰。有戎勿恤。得中道也。乾为道。二中位。" tabindex="-1">象曰。有戎勿恤。得中道也。乾为道。二中位。 <a class="header-anchor" href="#象曰。有戎勿恤。得中道也。乾为道。二中位。" aria-label="Permalink to “象曰。有戎勿恤。得中道也。乾为道。二中位。”">​</a></h3><p>九三。壮于顶 有凶。君子决夬独行。遇雨。若儒。有愠。无咎。</p><p>顾（左九）面颧也。三居下卦之上。故曰颁（左九）。而四五皆阳。故伤及于颀（左九）。伤颀（左九）故凶。乾为君子。承乘皆阳遇敌。故决夬独行。而应在上。上兑为雨。故曰遇雨。曰若濡。濡。雨（下沾）湿也。乾为衣。衣濡故温。然究为正应。亦无咎也。</p><h3 id="象曰。君子决夬。终无咎也。" tabindex="-1">象曰。君子决夬。终无咎也。 <a class="header-anchor" href="#象曰。君子决夬。终无咎也。" aria-label="Permalink to “象曰。君子决夬。终无咎也。”">​</a></h3><p>决夬独行状。三于四五虽遇敌。于卜独有应。故曰终无咎。终谓上。</p><p>九四。臀无肤。其行次且。牵羊悔亡。闻言不信。</p><p>伏艮为肤。为尾。故为臀。臀尾闾也。艮伏故曰元肤。乾为行。承乘皆阳。失位。故其行次且。次且。马云却行不前也。兑为羊。玉篇牵速也。娠九三云。行未牵也。亦以奉为速。次且行缓。速则无悔。牵羊悔亡者。言四宜随五。速进决阴。阴决则当位居五。故曰悔亡。旧说皆不知悔亡之故何在。则以牵字失诂也。兑为耳。故曰闻。乾为言为信。兑口亦为言。闻言不信者。兑言向外。与乾言相背。故不信也。兑耳象。鼎传云。翼而耳目聪明。目谓上离。耳谓互兑也。</p><h3 id="象曰。其行次且。位不当也。闻言不信。聪不明也。" tabindex="-1">象曰。其行次且。位不当也。闻言不信。聪不明也。 <a class="header-anchor" href="#象曰。其行次且。位不当也。闻言不信。聪不明也。" aria-label="Permalink to “象曰。其行次且。位不当也。闻言不信。聪不明也。”">​</a></h3><p>兑为耳。为黯昧。故曰不明。不明犹不审。俗所谓不清。虞氏以离目当之。非。</p><p>九五。觅陆决夬。中行无咎。</p><p>盂喜云。觅陆兽名。夬有兑。兑为羊也。说文亦云昆山羊细角。诸家说此二字。人人异辞。独孟氏于象密合。凡五皆谓中行。又决夬于羊行貌独切。郑虞等训克陆为草属。草焉有决夬之象哉。</p><h3 id="象曰。中行无咎。中未光也。" tabindex="-1">象曰。中行无咎。中未光也。 <a class="header-anchor" href="#象曰。中行无咎。中未光也。" aria-label="Permalink to “象曰。中行无咎。中未光也。”">​</a></h3><p>兑黯昧。故未光。</p><p>上六。无号。终有凶。</p><p>一阴在上。为阳所推。不能久也。兑为口故曰号。无号终有凶者。言不必号号眺（左口）。必消灭也。</p><h3 id="象曰。无号之凶。终不可长也。" tabindex="-1">象曰。无号之凶。终不可长也。 <a class="header-anchor" href="#象曰。无号之凶。终不可长也。" aria-label="Permalink to “象曰。无号之凶。终不可长也。”">​</a></h3><p>不可长。言不能长久。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
